('f8888888-8888-4888-8888-888888888888', 13, 'If I were you, I would accept.', '', 'Se eu fosse você, eu aceitaria.', 'I', 'would accept', 'if I were you'),
('f8888888-8888-4888-8888-888888888888', 14, 'I cannot stand the traffic.', '', 'Não suporto o trânsito.', 'I', 'cannot stand', 'the traffic'),
('f8888888-8888-4888-8888-888888888888', 15, 'Let''s keep in touch.', '', 'Vamos manter contato.', 'Let''s', 'keep', 'in touch'),
('f8888888-8888-4888-8888-888888888888', 16, 'I look forward to hearing from you.', '', 'Estou ansioso para ter notícias suas.', 'I', 'look forward', 'to hearing from you'),
('f8888888-8888-4888-8888-888888888888', 17, 'That makes perfect sense.', '', 'Isso faz todo o sentido.', 'That', 'makes', 'perfect sense'),
('f8888888-8888-4888-8888-888888888888', 18, 'To be honest, I was surprised.', '', 'Para ser honesto, fiquei surpreso.', 'I', 'was', 'surprised, to be honest'),
('f8888888-8888-4888-8888-888888888888', 19, 'It is up to you.', '', 'É com você.', 'It', 'is', 'up to you'),
('f8888888-8888-4888-8888-888888888888', 20, 'I have been learning English for two years.', '', 'Eu estudo inglês há dois anos.', 'I', 'have been learning', 'English for two years');
INSERT INTO planet_sentences (planet_id, position, en, es, pt, subject, verb, complement) VALUES
('44444444-4444-4444-8444-444444444444', 21, 'The soup is delicious today.', '', 'A sopa está deliciosa hoje.', 'The soup', 'is', 'delicious today'),
('44444444-4444-4444-8444-444444444444', 22, 'Could I have some more water?', '', 'Posso ter mais um pouco de água?', 'I', 'could have', 'some more water'),
('44444444-4444-4444-8444-444444444444', 23, 'I eat fruit every morning.', '', 'Como frutas todas as manhãs.', 'I', 'eat', 'fruit every morning'),
('44444444-4444-4444-8444-444444444444', 24, 'What is your favorite food?', '', 'Qual é a sua comida favorita?', 'your favorite food', 'is', 'what'),
('44444444-4444-4444-8444-444444444444', 25, 'I do not like spicy food.', '', 'Não gosto de comida picante.', 'I', 'do not like', 'spicy food'),
('44444444-4444-4444-8444-444444444444', 26, 'Let''s have lunch together.', '', 'Vamos almoçar juntos.', 'Let''s', 'have', 'lunch together'),
('44444444-4444-4444-8444-444444444444', 27, 'The cake is very sweet.', '', 'O bolo está muito doce.', 'The cake', 'is', 'very sweet'),
('44444444-4444-4444-8444-444444444444', 28, 'I am on a diet.', '', 'Estou de dieta.', 'I', 'am', 'on a diet'),
('44444444-4444-4444-8444-444444444444', 29, 'Do you want some more coffee?', '', 'Você quer mais um pouco de café?', 'you', 'want', 'some more coffee'),
('44444444-4444-4444-8444-444444444444', 30, 'This fruit is not ripe yet.', '', 'Esta fruta ainda não está madura.', 'This fruit', 'is', 'not ripe yet'),
('55555555-5555-4555-8555-555555555555', 21, 'Where can I buy a ticket?', '', 'Onde posso comprar uma passagem?', 'I', 'can buy', 'a ticket where'),
('55555555-5555-4555-8555-555555555555', 22, 'The map shows the way.', '', 'O mapa mostra o caminho.', 'The map', 'shows', 'the way'),
('55555555-5555-4555-8555-555555555555', 23, 'Is the hotel far from here?', '', 'O hotel fica longe daqui?', 'the hotel', 'is', 'far from here'),
('55555555-5555-4555-8555-555555555555', 24, 'I need to change trains.', '', 'Preciso trocar de trem.', 'I', 'need', 'to change trains'),
('55555555-5555-4555-8555-555555555555', 25, 'We went sightseeing in the city.', '', 'Fizemos turismo pela cidade.', 'We', 'went', 'sightseeing in the city'),
('55555555-5555-4555-8555-555555555555', 26, 'The ticket costs twenty dollars.', '', 'A passagem custa vinte dólares.', 'The ticket', 'costs', 'twenty dollars'),
('55555555-5555-4555-8555-555555555555', 27, 'When does the next bus leave?', '', 'Quando sai o próximo ônibus?', 'the next bus', 'leaves', 'when'),
('55555555-5555-4555-8555-555555555555', 28, 'I travel by plane every year.', '', 'Viajo de avião todos os anos.', 'I', 'travel', 'by plane every year'),
('55555555-5555-4555-8555-555555555555', 29, 'Can you take a photo of us?', '', 'Você pode tirar uma foto nossa?', 'you', 'can take', 'a photo of us'),
('55555555-5555-4555-8555-555555555555', 30, 'We arrived at the hotel at night.', '', 'Chegamos ao hotel à noite.', 'We', 'arrived', 'at the hotel at night'),
('66666666-6666-4666-8666-666666666666', 21, 'I am feeling tired today.', '', 'Estou me sentindo cansado hoje.', 'I', 'am feeling', 'tired today'),
('66666666-6666-4666-8666-666666666666', 22, 'She is very happy with the news.', '', 'Ela está muito feliz com a notícia.', 'She', 'is', 'very happy with the news'),
('66666666-6666-4666-8666-666666666666', 23, 'Take this medicine after lunch.', '', 'Tome este remédio depois do almoço.', 'You', 'take', 'this medicine after lunch'),
('66666666-6666-4666-8666-666666666666', 24, 'My back hurts.', '', 'Minhas costas doem.', 'My back', 'hurts', ''),
('66666666-6666-4666-8666-666666666666', 25, 'Are you afraid of the dark?', '', 'Você tem medo do escuro?', 'you', 'are', 'afraid of the dark'),
('66666666-6666-4666-8666-666666666666', 26, 'I am excited about the trip.', '', 'Estou animado com a viagem.', 'I', 'am', 'excited about the trip'),
('66666666-6666-4666-8666-666666666666', 27, 'You look great today.', '', 'Você está ótimo hoje.', 'You', 'look', 'great today'),
('66666666-6666-4666-8666-666666666666', 28, 'I need to see a dentist.', '', 'Preciso ir ao dentista.', 'I', 'need', 'to see a dentist'),
('66666666-6666-4666-8666-666666666666', 29, 'She calmed down quickly.', '', 'Ela se acalmou rapidamente.', 'She', 'calmed', 'down quickly'),
('66666666-6666-4666-8666-666666666666', 30, 'Do not worry, everything will be fine.', '', 'Não se preocupe, tudo vai ficar bem.', 'You', 'worry', 'do not, everything will be fine'),
('77777777-7777-4777-8777-777777777777', 21, 'I sent the report this morning.', '', 'Enviei o relatório esta manhã.', 'I', 'sent', 'the report this morning'),
('77777777-7777-4777-8777-777777777777', 22, 'The client liked our proposal.', '', 'O cliente gostou da nossa proposta.', 'The client', 'liked', 'our proposal'),
('77777777-7777-4777-8777-777777777777', 23, 'We need one more week.', '', 'Precisamos de mais uma semana.', 'We', 'need', 'one more week'),
('77777777-7777-4777-8777-777777777777', 24, 'Can you review this document?', '', 'Você pode revisar este documento?', 'you', 'can review', 'this document'),
('77777777-7777-4777-8777-777777777777', 25, 'I will call you back this afternoon.', '', 'Vou te ligar de volta esta tarde.', 'I', 'will call', 'you back this afternoon'),
('77777777-7777-4777-8777-777777777777', 26, 'She works in the marketing team.', '', 'Ela trabalha na equipe de marketing.', 'She', 'works', 'in the marketing team'),
('77777777-7777-4777-8777-777777777777', 27, 'The meeting lasted two hours.', '', 'A reunião durou duas horas.', 'The meeting', 'lasted', 'two hours'),
('77777777-7777-4777-8777-777777777777', 28, 'Please confirm the appointment.', '', 'Por favor, confirme o compromisso.', 'You', 'confirm', 'the appointment, please'),
('77777777-7777-4777-8777-777777777777', 29, 'I have three meetings today.', '', 'Tenho três reuniões hoje.', 'I', 'have', 'three meetings today'),
('77777777-7777-4777-8777-777777777777', 30, 'Thank you for your time.', '', 'Obrigado pelo seu tempo.', '', '', 'Thank you for your time'),
('88888888-8888-4888-8888-888888888888', 21, 'It is hard to say.', '', 'É difícil dizer.', 'It', 'is', 'hard to say'),
('88888888-8888-4888-8888-888888888888', 22, 'I am looking forward to the weekend.', '', 'Estou ansioso pelo fim de semana.', 'I', 'am looking forward', 'to the weekend'),
('88888888-8888-4888-8888-888888888888', 23, 'That is a good question.', '', 'Essa é uma boa pergunta.', 'That', 'is', 'a good question'),
('88888888-8888-4888-8888-888888888888', 24, 'We have known each other for years.', '', 'Nos conhecemos há anos.', 'We', 'have known', 'each other for years'),
('88888888-8888-4888-8888-888888888888', 25, 'I would rather stay home tonight.', '', 'Prefiro ficar em casa esta noite.', 'I', 'would rather stay', 'home tonight'),
('88888888-8888-4888-8888-888888888888', 26, 'It took me a while to understand.', '', 'Levei um tempo para entender.', 'It', 'took', 'me a while to understand'),
('88888888-8888-4888-8888-888888888888', 27, 'To tell you the truth, I was worried.', '', 'Para falar a verdade, eu estava preocupado.', 'I', 'was', 'worried, to tell you the truth'),
('88888888-8888-4888-8888-888888888888', 28, 'That explains a lot.', '', 'Isso explica muita coisa.', 'That', 'explains', 'a lot'),
('88888888-8888-4888-8888-888888888888', 29, 'I am getting used to the city.', '', 'Estou me acostumando com a cidade.', 'I', 'am getting used', 'to the city'),
('88888888-8888-4888-8888-888888888888', 30, 'Let me think about it.', '', 'Deixe-me pensar sobre isso.', 'You', 'let', 'me think about it');
