('e4444444-4444-4444-8444-444444444444', 25, '', 'No me gusta la comida picante.', 'Não gosto de comida picante.', 'me', 'gusta', 'la comida picante'),
('e4444444-4444-4444-8444-444444444444', 26, '', 'Almorcemos juntos.', 'Vamos almoçar juntos.', 'nosotros', 'almorcemos', 'juntos'),
('e4444444-4444-4444-8444-444444444444', 27, '', 'El pastel está muy dulce.', 'O bolo está muito doce.', 'el pastel', 'está', 'muy dulce'),
('e4444444-4444-4444-8444-444444444444', 28, '', 'Estoy a dieta.', 'Estou de dieta.', 'yo', 'estoy', 'a dieta'),
('e4444444-4444-4444-8444-444444444444', 29, '', '¿Quieres más café?', 'Você quer mais um pouco de café?', 'tú', 'quieres', 'más café'),
