('e5555555-5555-4555-8555-555555555555', 23, '', '¿El hotel está lejos de aquí?', 'O hotel fica longe daqui?', 'el hotel', 'está', 'lejos de aquí'),
('e5555555-5555-4555-8555-555555555555', 24, '', 'Necesito cambiar de tren.', 'Preciso trocar de trem.', 'yo', 'necesito', 'cambiar de tren'),
('e5555555-5555-4555-8555-555555555555', 25, '', 'Hicimos turismo por la ciudad.', 'Fizemos turismo pela cidade.', 'nosotros', 'hicimos', 'turismo por la ciudad'),
('e5555555-5555-4555-8555-555555555555', 26, '', 'El billete cuesta veinte dólares.', 'A passagem custa vinte dólares.', 'el billete', 'cuesta', 'veinte dólares'),
('e5555555-5555-4555-8555-555555555555', 27, '', '¿Cuándo sale el próximo autobús?', 'Quando sai o próximo ônibus?', 'el próximo autobús', 'sale', 'cuándo'),
('e5555555-5555-4555-8555-555555555555', 28, '', 'Viajo en avión todos los años.', 'Viajo de avião todos os anos.', 'yo', 'viajo', 'en avión todos los años'),
('e5555555-5555-4555-8555-555555555555', 29, '', '¿Puedes sacarnos una foto?', 'Você pode tirar uma foto nossa?', 'tú', 'puedes sacar', 'nos una foto'),
('e5555555-5555-4555-8555-555555555555', 30, '', 'Llegamos al hotel por la noche.', 'Chegamos ao hotel à noite.', 'nosotros', 'llegamos', 'al hotel por la noche'),
('e6666666-6666-4666-8666-666666666666', 21, '', 'Me siento cansado hoy.', 'Estou me sentindo cansado hoje.', 'yo', 'me siento', 'cansado hoy'),
('e6666666-6666-4666-8666-666666666666', 22, '', 'Ella está muy feliz con la noticia.', 'Ela está muito feliz com a notícia.', 'ella', 'está', 'muy feliz con la noticia'),
('e6666666-6666-4666-8666-666666666666', 23, '', 'Toma esta medicina después del almuerzo.', 'Tome este remédio depois do almoço.', 'tú', 'toma', 'esta medicina después del almuerzo'),
('e6666666-6666-4666-8666-666666666666', 24, '', 'Me duele la espalda.', 'Minhas costas doem.', 'me', 'duele', 'la espalda'),
('e6666666-6666-4666-8666-666666666666', 25, '', '¿Tienes miedo a la oscuridad?', 'Você tem medo do escuro?', 'tú', 'tienes', 'miedo a la oscuridad'),
