('e6666666-6666-4666-8666-666666666666', 27, '', 'Te ves genial hoy.', 'Você está ótimo hoje.', 'tú', 'te ves', 'genial hoy'),
('e6666666-6666-4666-8666-666666666666', 28, '', 'Necesito ir al dentista.', 'Preciso ir ao dentista.', 'yo', 'necesito', 'ir al dentista'),
('e6666666-6666-4666-8666-666666666666', 29, '', 'Ella se calmó rápidamente.', 'Ela se acalmou rapidamente.', 'ella', 'se calmó', 'rápidamente'),
('e6666666-6666-4666-8666-666666666666', 30, '', 'No te preocupes, todo estará bien.', 'Não se preocupe, tudo vai ficar bem.', 'tú', 'te preocupes', 'no, todo estará bien'),
