('e7777777-7777-4777-8777-777777777777', 23, '', 'Necesitamos una semana más.', 'Precisamos de mais uma semana.', 'nosotros', 'necesitamos', 'una semana más'),
('e7777777-7777-4777-8777-777777777777', 24, '', '¿Puedes revisar este documento?', 'Você pode revisar este documento?', 'tú', 'puedes revisar', 'este documento'),
('e7777777-7777-4777-8777-777777777777', 25, '', 'Te llamaré de nuevo esta tarde.', 'Vou te ligar de volta esta tarde.', 'yo', 'llamaré', 'te de nuevo esta tarde'),
('e7777777-7777-4777-8777-777777777777', 26, '', 'Ella trabaja en el equipo de marketing.', 'Ela trabalha na equipe de marketing.', 'ella', 'trabaja', 'en el equipo de marketing'),
('e7777777-7777-4777-8777-777777777777', 27, '', 'La reunión duró dos horas.', 'A reunião durou duas horas.', 'la reunión', 'duró', 'dos horas'),
('e7777777-7777-4777-8777-777777777777', 28, '', 'Por favor, confirma la cita.', 'Por favor, confirme o compromisso.', 'tú', 'confirma', 'la cita, por favor'),
('e7777777-7777-4777-8777-777777777777', 29, '', 'Tengo tres reuniones hoy.', 'Tenho três reuniões hoje.', 'yo', 'tengo', 'tres reuniones hoy'),
('e7777777-7777-4777-8777-777777777777', 30, '', 'Gracias por tu tiempo.', 'Obrigado pelo seu tempo.', '', '', 'Gracias por tu tiempo'),
('e8888888-8888-4888-8888-888888888888', 21, '', 'Es difícil de decir.', 'É difícil dizer.', 'es', 'difícil', 'de decir'),
('e8888888-8888-4888-8888-888888888888', 22, '', 'Espero con ganas el fin de semana.', 'Estou ansioso pelo fim de semana.', 'yo', 'espero', 'con ganas el fin de semana'),
('e8888888-8888-4888-8888-888888888888', 23, '', 'Esa es una buena pregunta.', 'Essa é uma boa pergunta.', 'esa', 'es', 'una buena pregunta'),
('e8888888-8888-4888-8888-888888888888', 24, '', 'Nos conocemos desde hace años.', 'Nos conhecemos há anos.', 'nosotros', 'nos conocemos', 'desde hace años'),
('e8888888-8888-4888-8888-888888888888', 25, '', 'Prefiero quedarme en casa esta noche.', 'Prefiro ficar em casa esta noite.', 'yo', 'prefiero', 'quedarme en casa esta noche'),
('e8888888-8888-4888-8888-888888888888', 26, '', 'Me tomó un tiempo entender.', 'Levei um tempo para entender.', 'me', 'tomó', 'un tiempo entender'),
('e8888888-8888-4888-8888-888888888888', 27, '', 'Para decirte la verdad, estaba preocupado.', 'Para falar a verdade, eu estava preocupado.', 'yo', 'estaba', 'preocupado, para decirte la verdad'),
('e8888888-8888-4888-8888-888888888888', 28, '', 'Eso explica muchas cosas.', 'Isso explica muita coisa.', 'eso', 'explica', 'muchas cosas'),
('e8888888-8888-4888-8888-888888888888', 29, '', 'Me estoy acostumbrando a la ciudad.', 'Estou me acostumando com a cidade.', 'yo', 'me estoy acostumbrando', 'a la ciudad'),
('e8888888-8888-4888-8888-888888888888', 30, '', 'Déjame pensarlo.', 'Deixe-me pensar sobre isso.', 'tú', 'déjame', 'pensarlo');
