('f6666666-6666-4666-8666-666666666666', 29, 'She calmed down quickly.', '', 'Ela se acalmou rapidamente.', 'She', 'calmed', 'down quickly'),
('f6666666-6666-4666-8666-666666666666', 30, 'Do not worry, everything will be fine.', '', 'Não se preocupe, tudo vai ficar bem.', 'You', 'worry', 'do not, everything will be fine'),
('f7777777-7777-4777-8777-777777777777', 21, 'I sent the report this morning.', '', 'Enviei o relatório esta manhã.', 'I', 'sent', 'the report this morning'),
('f7777777-7777-4777-8777-777777777777', 22, 'The client liked our proposal.', '', 'O cliente gostou da nossa proposta.', 'The client', 'liked', 'our proposal'),
('f7777777-7777-4777-8777-777777777777', 23, 'We need one more week.', '', 'Precisamos de mais uma semana.', 'We', 'need', 'one more week'),
('f7777777-7777-4777-8777-777777777777', 24, 'Can you review this document?', '', 'Você pode revisar este documento?', 'you', 'can review', 'this document'),
('f7777777-7777-4777-8777-777777777777', 25, 'I will call you back this afternoon.', '', 'Vou te ligar de volta esta tarde.', 'I', 'will call', 'you back this afternoon'),
('f7777777-7777-4777-8777-777777777777', 26, 'She works in the marketing team.', '', 'Ela trabalha na equipe de marketing.', 'She', 'works', 'in the marketing team'),
('f7777777-7777-4777-8777-777777777777', 27, 'The meeting lasted two hours.', '', 'A reunião durou duas horas.', 'The meeting', 'lasted', 'two hours'),
('f7777777-7777-4777-8777-777777777777', 28, 'Please confirm the appointment.', '', 'Por favor, confirme o compromisso.', 'You', 'confirm', 'the appointment, please'),
('f7777777-7777-4777-8777-777777777777', 29, 'I have three meetings today.', '', 'Tenho três reuniões hoje.', 'I', 'have', 'three meetings today'),
('f7777777-7777-4777-8777-777777777777', 30, 'Thank you for your time.', '', 'Obrigado pelo seu tempo.', '', '', 'Thank you for your time'),
