('f8888888-8888-4888-8888-888888888888', 22, 'I am looking forward to the weekend.', '', 'Estou ansioso pelo fim de semana.', 'I', 'am looking forward', 'to the weekend'),
('f8888888-8888-4888-8888-888888888888', 23, 'That is a good question.', '', 'Essa é uma boa pergunta.', 'That', 'is', 'a good question'),
('f8888888-8888-4888-8888-888888888888', 24, 'We have known each other for years.', '', 'Nos conhecemos há anos.', 'We', 'have known', 'each other for years'),
('f8888888-8888-4888-8888-888888888888', 25, 'I would rather stay home tonight.', '', 'Prefiro ficar em casa esta noite.', 'I', 'would rather stay', 'home tonight'),
('f8888888-8888-4888-8888-888888888888', 26, 'It took me a while to understand.', '', 'Levei um tempo para entender.', 'It', 'took', 'me a while to understand'),
('f8888888-8888-4888-8888-888888888888', 27, 'To tell you the truth, I was worried.', '', 'Para falar a verdade, eu estava preocupado.', 'I', 'was', 'worried, to tell you the truth'),
('f8888888-8888-4888-8888-888888888888', 28, 'That explains a lot.', '', 'Isso explica muita coisa.', 'That', 'explains', 'a lot'),
('f8888888-8888-4888-8888-888888888888', 29, 'I am getting used to the city.', '', 'Estou me acostumando com a cidade.', 'I', 'am getting used', 'to the city'),
('f8888888-8888-4888-8888-888888888888', 30, 'Let me think about it.', '', 'Deixe-me pensar sobre isso.', 'You', 'let', 'me think about it');
