('66666666-6666-4666-8666-666666666666', 34, 'She feels a little sick.', '', 'Ela está se sentindo um pouco doente.', 'She', 'feels', 'a little sick'),
('66666666-6666-4666-8666-666666666666', 35, 'Take a deep breath.', '', 'Respire fundo.', 'You', 'take', 'a deep breath'),
