('66666666-6666-4666-8666-666666666666', 49, 'I got sick last night.', '', 'Fiquei doente ontem à noite.', 'I', 'got', 'sick last night'),
('66666666-6666-4666-8666-666666666666', 50, 'Stay calm and keep trying.', '', 'Fique calmo e continue tentando.', 'You', 'stay', 'calm and keep trying'),
