('77777777-7777-4777-8777-777777777777', 34, 'The office opens at nine.', '', 'O escritório abre às nove.', 'The office', 'opens', 'at nine'),
('77777777-7777-4777-8777-777777777777', 35, 'I will call you back later.', '', 'Vou te ligar de volta mais tarde.', 'I', 'will call', 'you back later'),
('77777777-7777-4777-8777-777777777777', 36, 'The project is going well.', '', 'O projeto está indo bem.', 'The project', 'is going', 'well'),
