('77777777-7777-4777-8777-777777777777', 49, 'She works part-time.', '', 'Ela trabalha meio período.', 'She', 'works', 'part-time'),
('77777777-7777-4777-8777-777777777777', 50, 'Thank you for your patience.', '', 'Obrigado pela sua paciência.', '', '', 'Thank you for your patience'),
