('f6666666-6666-4666-8666-666666666666', 50, 'Stay calm and keep trying.', '', 'Fique calmo e continue tentando.', 'You', 'stay', 'calm and keep trying'),
('f7777777-7777-4777-8777-777777777777', 31, 'I will send the report by email.', '', 'Vou enviar o relatório por e-mail.', 'I', 'will send', 'the report by email'),
('f7777777-7777-4777-8777-777777777777', 32, 'Who is responsible for this project?', '', 'Quem é responsável por este projeto?', 'who', 'is', 'responsible for this project'),
('f7777777-7777-4777-8777-777777777777', 33, 'We need more time.', '', 'Precisamos de mais tempo.', 'We', 'need', 'more time'),
('f7777777-7777-4777-8777-777777777777', 34, 'The office opens at nine.', '', 'O escritório abre às nove.', 'The office', 'opens', 'at nine'),
('f7777777-7777-4777-8777-777777777777', 35, 'I will call you back later.', '', 'Vou te ligar de volta mais tarde.', 'I', 'will call', 'you back later'),
('f7777777-7777-4777-8777-777777777777', 36, 'The project is going well.', '', 'O projeto está indo bem.', 'The project', 'is going', 'well'),
('f7777777-7777-4777-8777-777777777777', 37, 'Could you send me the details?', '', 'Você poderia me enviar os detalhes?', 'you', 'could send', 'me the details'),
('f7777777-7777-4777-8777-777777777777', 38, 'I work better in the morning.', '', 'Trabalho melhor de manhã.', 'I', 'work', 'better in the morning'),
('f7777777-7777-4777-8777-777777777777', 39, 'The client is waiting for us.', '', 'O cliente está nos esperando.', 'The client', 'is waiting', 'for us'),
('f7777777-7777-4777-8777-777777777777', 40, 'We are hiring new people.', '', 'Estamos contratando novas pessoas.', 'We', 'are hiring', 'new people'),
('f7777777-7777-4777-8777-777777777777', 41, 'This task is very simple.', '', 'Esta tarefa é muito simples.', 'This task', 'is', 'very simple'),
('f7777777-7777-4777-8777-777777777777', 42, 'Did you receive my message?', '', 'Você recebeu minha mensagem?', 'you', 'did receive', 'my message'),
('f7777777-7777-4777-8777-777777777777', 43, 'I have a full schedule today.', '', 'Tenho uma agenda cheia hoje.', 'I', 'have', 'a full schedule today'),
('f7777777-7777-4777-8777-777777777777', 44, 'The company is growing fast.', '', 'A empresa está crescendo rápido.', 'The company', 'is growing', 'fast'),
('f7777777-7777-4777-8777-777777777777', 45, 'Let''s discuss this tomorrow.', '', 'Vamos discutir isso amanhã.', 'Let''s', 'discuss', 'this tomorrow'),
('f7777777-7777-4777-8777-777777777777', 46, 'I am in charge of the team.', '', 'Estou no comando da equipe.', 'I', 'am', 'in charge of the team'),
('f7777777-7777-4777-8777-777777777777', 47, 'The payment is due on Friday.', '', 'O pagamento vence na sexta-feira.', 'The payment', 'is due', 'on Friday'),
('f7777777-7777-4777-8777-777777777777', 48, 'We had a great meeting.', '', 'Tivemos uma ótima reunião.', 'We', 'had', 'a great meeting'),
('f7777777-7777-4777-8777-777777777777', 49, 'She works part-time.', '', 'Ela trabalha meio período.', 'She', 'works', 'part-time'),
('f7777777-7777-4777-8777-777777777777', 50, 'Thank you for your patience.', '', 'Obrigado pela sua paciência.', '', '', 'Thank you for your patience'),
('f8888888-8888-4888-8888-888888888888', 31, 'I completely disagree.', '', 'Discordo completamente.', 'I', 'disagree', 'completely'),
('f8888888-8888-4888-8888-888888888888', 32, 'It depends on how you look at it.', '', 'Depende de como você vê as coisas.', 'It', 'depends', 'on how you look at it'),
