('f8888888-8888-4888-8888-888888888888', 34, 'I have no idea.', '', 'Não faço ideia.', 'I', 'have', 'no idea'),
('f8888888-8888-4888-8888-888888888888', 35, 'It is worth trying.', '', 'Vale a pena tentar.', 'It', 'is', 'worth trying'),
('f8888888-8888-4888-8888-888888888888', 36, 'I changed my mind.', '', 'Mudei de ideia.', 'I', 'changed', 'my mind'),
('f8888888-8888-4888-8888-888888888888', 37, 'Honestly, I do not know.', '', 'Sinceramente, não sei.', 'I', 'do not know', 'honestly'),
('f8888888-8888-4888-8888-888888888888', 38, 'That sounds great to me.', '', 'Isso parece ótimo para mim.', 'That', 'sounds', 'great to me'),
('f8888888-8888-4888-8888-888888888888', 39, 'I am in the middle of something.', '', 'Estou no meio de uma coisa.', 'I', 'am', 'in the middle of something'),
('f8888888-8888-4888-8888-888888888888', 40, 'It is never too late.', '', 'Nunca é tarde demais.', 'It', 'is', 'never too late'),
('f8888888-8888-4888-8888-888888888888', 41, 'As you wish.', '', 'Como você quiser.', 'you', 'wish', 'as'),
('f8888888-8888-4888-8888-888888888888', 42, 'I am afraid we are late.', '', 'Receio que estejamos atrasados.', 'I', 'am afraid', 'we are late'),
('f8888888-8888-4888-8888-888888888888', 43, 'It makes no difference to me.', '', 'Não faz diferença para mim.', 'It', 'makes', 'no difference to me'),
('f8888888-8888-4888-8888-888888888888', 44, 'I have heard that before.', '', 'Já ouvi isso antes.', 'I', 'have heard', 'that before'),
('f8888888-8888-4888-8888-888888888888', 45, 'You are absolutely right.', '', 'Você tem toda a razão.', 'You', 'are', 'absolutely right'),
('f8888888-8888-4888-8888-888888888888', 46, 'That is a different story.', '', 'Isso é outra história.', 'That', 'is', 'a different story'),
('f8888888-8888-4888-8888-888888888888', 47, 'I cannot wait to see you.', '', 'Mal posso esperar para te ver.', 'I', 'cannot wait', 'to see you'),
('f8888888-8888-4888-8888-888888888888', 48, 'Everything is under control.', '', 'Está tudo sob controle.', 'Everything', 'is', 'under control'),
('f8888888-8888-4888-8888-888888888888', 49, 'The more, the merrier.', '', 'Quanto mais, melhor.', '', '', 'The more, the merrier'),
