-- ---------------------------------------------------------------------------
-- 2. Spanish course (pt -> es): target es, base pt
-- ---------------------------------------------------------------------------


-- ---------------------------------------------------------------------------
-- 3. Portuguese course (en -> pt): target pt, base en
-- ---------------------------------------------------------------------------


-- ---------------------------------------------------------------------------
-- 4. Second batch — planets 4-8 (positions 21-30, ~30 sentences each).
--    Authored in the same three courses; the mirror below picks them up via
--    the position >= 7 filter (planets != 1).
-- ---------------------------------------------------------------------------




-- ---------------------------------------------------------------------------
-- 5. Third batch — planets 4-8 (positions 31-50, ~50 sentences each).
--    Authored in the same three courses; the mirror below picks them up via
--    the position >= 7 filter (planets != 1). The derived courses have no
--    rows >= 31 until that mirror runs, so nothing collides there either.
-- ---------------------------------------------------------------------------

-- English course (pt -> en): target en, base pt

-- Spanish course (pt -> es): target es, base pt

-- Portuguese course (en -> pt): target pt, base en

-- ---------------------------------------------------------------------------
-- 6. Mirror into the derived courses (es->en, en->es, es->pt) with the same
--    number/position alignment the full-language-matrix migration used.
-- ---------------------------------------------------------------------------

-- es->en: en = English target (pt->en course), es = Spanish base (pt->es course)
-- Only the NEW rows are copied — the pre-existing positions already live in
-- the derived courses (the matrix migration created them), so copying them
-- again would violate the unique (planet_id, position) constraint.
SELECT np.id, src.position, src.en, ses.es, '', src.subject, src.verb, src.complement
FROM planet_sentences src
JOIN planets sp   ON sp.id = src.planet_id AND sp.language = 'en' AND sp.base_language = 'pt'
JOIN planets np   ON np.number = sp.number AND np.language = 'en' AND np.base_language = 'es'
JOIN planets esp  ON esp.number = sp.number AND esp.language = 'es' AND esp.base_language = 'pt'
JOIN planet_sentences ses ON ses.planet_id = esp.id AND ses.position = src.position
WHERE src.position >= CASE WHEN sp.number = 1 THEN 11 ELSE 7 END
ORDER BY np.number, src.position;

-- en->es: es = Spanish target (pt->es course), en = English base (pt->en course)
SELECT np.id, src.position, eng2.en, src.es, '', src.subject, src.verb, src.complement
FROM planet_sentences src
JOIN planets sp   ON sp.id = src.planet_id AND sp.language = 'es' AND sp.base_language = 'pt'
JOIN planets np   ON np.number = sp.number AND np.language = 'es' AND np.base_language = 'en'
JOIN planets eng  ON eng.number = sp.number AND eng.language = 'en' AND eng.base_language = 'pt'
JOIN planet_sentences eng2 ON eng2.planet_id = eng.id AND eng2.position = src.position
WHERE src.position >= CASE WHEN sp.number = 1 THEN 11 ELSE 7 END
ORDER BY np.number, src.position;

-- es->pt: pt = Portuguese target (en->pt course), es = Spanish base (pt->es course)
SELECT np.id, src.position, '', ses.es, src.pt, src.subject, src.verb, src.complement
FROM planet_sentences src
JOIN planets sp   ON sp.id = src.planet_id AND sp.language = 'pt' AND sp.base_language = 'en'
JOIN planets np   ON np.number = sp.number AND np.language = 'pt' AND np.base_language = 'es'
JOIN planets esp  ON esp.number = sp.number AND esp.language = 'es' AND esp.base_language = 'pt'
JOIN planet_sentences ses ON ses.planet_id = esp.id AND ses.position = src.position
WHERE src.position >= CASE WHEN sp.number = 1 THEN 11 ELSE 7 END
ORDER BY np.number, src.position;
